    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
    public record ReferenceData(string Name, string Relationship, string Email, string Phone);

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        SubmitError = null;
        try
        {
            ApplicationId = await SubmitFunc();
            IsSubmitted = true;
            await OnSubmitted.InvokeAsync(ApplicationId);
