@namespace sv_b4808de9fc594ad781a7ebb816f7d2dc.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company *</label>
            <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(Entry.Company))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(Entry.Title))" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e)" class="form-control" />
        </div>
        <div class="form-group">
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => UpdateEndDate(e)" class="form-control" />
            }
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(e, nameof(Entry.Description))" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        switch (field)
        {
            case nameof(Entry.Company): Entry.Company = value; break;
            case nameof(Entry.Title): Entry.Title = value; break;
            case nameof(Entry.Description): Entry.Description = value; break;
        }
        OnChanged.InvokeAsync(Entry);
    }

    private void UpdateStartDate(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            Entry.StartDate = date;
            OnChanged.InvokeAsync(Entry);
        }
    }

    private void UpdateEndDate(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            Entry.EndDate = date;
            OnChanged.InvokeAsync(Entry);
        }
    }

    private void ToggleCurrent(ChangeEventArgs e)
    {
        Entry.EndDate = (bool.TryParse(e.Value?.ToString(), out var val) && val) ? null : DateTime.Today;
        OnChanged.InvokeAsync(Entry);
    }
}

