@namespace sv_b4808de9fc594ad781a7ebb816f7d2dc.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger-sm" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name" @onchange="e => Update(e, nameof(Entry.Name))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship" @onchange="e => Update(e, nameof(Entry.Relationship))" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="e => Update(e, nameof(Entry.Email))" class="form-control" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Entry.Phone" @onchange="e => Update(e, nameof(Entry.Phone))" class="form-control" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        switch (field)
        {
            case nameof(Entry.Name): Entry.Name = value; break;
            case nameof(Entry.Relationship): Entry.Relationship = value; break;
            case nameof(Entry.Email): Entry.Email = value; break;
            case nameof(Entry.Phone): Entry.Phone = value; break;
        }
        OnChanged.InvokeAsync(Entry);
    }
}

